import{_ as a,o as s,c as i,a0 as t}from"./chunks/framework.DhQjJcnt.js";const g=JSON.parse('{"title":"Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"en/config.md","filePath":"en/config.md","lastUpdated":null}'),n={name:"en/config.md"};function o(l,e,d,r,p,c){return s(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h1><p>frp-sh uses a TOML config file (specified with <code>--config</code>). Without one, built-in defaults apply (pointing at <code>127.0.0.1</code>, for local testing only).</p><h2 id="first-run-wizard" tabindex="-1">First-run wizard <a class="header-anchor" href="#first-run-wizard" aria-label="Permalink to &quot;First-run wizard&quot;">​</a></h2><p>Running <code>frp-sh</code> with no arguments (or <code>frp-sh config</code>) opens an <strong>interactive setup wizard</strong>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  frp-sh setup wizard</span></span>
<span class="line"><span>  ==================</span></span>
<span class="line"><span>  1. Signaling server address (HTTP) [default http://127.0.0.1:8080]</span></span>
<span class="line"><span>  &gt; http://101.43.41.195:8080</span></span>
<span class="line"><span>  2. Relay server address (TCP) [default 101.43.41.195:8081]</span></span>
<span class="line"><span>  &gt;</span></span>
<span class="line"><span>  3. Separate UDP probe port? (y/N)</span></span></code></pre></div><ul><li>The <code>http://</code> prefix is optional (auto-completed)</li><li>The relay address defaults to the signaling host + <code>:8081</code>; just press Enter</li><li>After saving, a quick connectivity check (<code>/health</code>) runs automatically</li><li>The config is saved to the platform default location and loaded by every command afterwards: <ul><li>Windows: <code>%APPDATA%\\frp-sh\\config.toml</code></li><li>Linux/macOS: <code>~/.config/frp-sh/config.toml</code></li></ul></li><li>Re-configure with <code>frp-sh config</code>, or use <code>--config &lt;path&gt;</code> for an explicit file</li></ul><h2 id="fields" tabindex="-1">Fields <a class="header-anchor" href="#fields" aria-label="Permalink to &quot;Fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>signaling_addr</code></td><td>no</td><td><code>http://127.0.0.1:8080</code></td><td>signaling server HTTP base URL</td></tr><tr><td><code>relay_addr</code></td><td>no</td><td><code>127.0.0.1:8081</code></td><td>relay TCP address</td></tr><tr><td><code>signaling_udp</code></td><td>no</td><td>same port as HTTP</td><td>UDP probe address (when using a separate port)</td></tr></tbody></table><h2 id="example-connect-to-a-remote-server" tabindex="-1">Example: connect to a remote server <a class="header-anchor" href="#example-connect-to-a-remote-server" aria-label="Permalink to &quot;Example: connect to a remote server&quot;">​</a></h2><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># config/server.toml</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">signaling_addr = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http://101.43.41.195:8080&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">relay_addr     = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;101.43.41.195:8081&quot;</span></span></code></pre></div><p>Usage:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">frp-sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config/server.toml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> game</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">frp-sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config/server.toml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> game</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> join</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> game-a3f9c2</span></span></code></pre></div><h2 id="example-separate-udp-probe-port" tabindex="-1">Example: separate UDP probe port <a class="header-anchor" href="#example-separate-udp-probe-port" aria-label="Permalink to &quot;Example: separate UDP probe port&quot;">​</a></h2><p>Use this when a cloud firewall requires separate TCP/UDP ports:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">signaling_addr = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http://101.43.41.195:8080&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">relay_addr     = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;101.43.41.195:8081&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">signaling_udp  = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;101.43.41.195:8082&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # UDP probe on 8082</span></span></code></pre></div><p>The server side must then provide the UDP probe on <code>--addr 0.0.0.0:8082</code> (or a compatible endpoint).</p><h2 id="field-details" tabindex="-1">Field details <a class="header-anchor" href="#field-details" aria-label="Permalink to &quot;Field details&quot;">​</a></h2><h3 id="signaling-addr" tabindex="-1">signaling_addr <a class="header-anchor" href="#signaling-addr" aria-label="Permalink to &quot;signaling_addr&quot;">​</a></h3><p>REST API base URL:</p><ul><li><code>POST /room/create</code> — register a room</li><li><code>GET /room/{id}</code> — query a room</li><li><code>POST /room/{id}/join</code> — guest registration</li><li><code>DELETE /room/{id}</code> — close a room</li></ul><h3 id="signaling-udp" tabindex="-1">signaling_udp <a class="header-anchor" href="#signaling-udp" aria-label="Permalink to &quot;signaling_udp&quot;">​</a></h3><p>UDP probe endpoint: the client sends <code>ECHO &lt;token&gt;</code>; the server replies <code>ADDR &lt;token&gt; &lt;ip&gt;:&lt;port&gt;</code>, which tells the client its NAT-mapped public address.</p><blockquote><p>Probing must use the <strong>same socket as punching</strong> (same local port), so the advertised address is the mapping that punching can actually use.</p></blockquote><h3 id="relay-addr" tabindex="-1">relay_addr <a class="header-anchor" href="#relay-addr" aria-label="Permalink to &quot;relay_addr&quot;">​</a></h3><p>The TCP relay endpoint used when punching fails. After connecting, send <code>HELLO &lt;room_id&gt; &lt;HOST|GUEST&gt;</code> to pair.</p><h2 id="precedence" tabindex="-1">Precedence <a class="header-anchor" href="#precedence" aria-label="Permalink to &quot;Precedence&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>command-line options &gt; config file &gt; built-in defaults</span></span></code></pre></div><p>Currently the <code>serve</code> listen addresses are controlled by command-line options only; client addresses come from the config file.</p>`,28)])])}const u=a(n,[["render",o]]);export{g as __pageData,u as default};
